examples.code:
// At the start of the scene, the event opens its own track
local hEvSnd = CMND_SND_OPEN_BGM("M_08");
// ... scene ...

// At the end, hand that track over to the match so it keeps playing
// (the ev_main wrapper calls CMND_BTL_CONTINUOUS_BGM("M_08"))
ScEventContinuousBGMAtMatch("M_08");
EndScEvent(isEvUpperDisp, scEvHdl);

// With the default empty name the native does nothing
ScEventContinuousBGMAtMatch <- function ( _bgmid = "" )
{
	CMND_BTL_CONTINUOUS_BGM(_bgmid);
};
